export function paginateCursor(items, { limit = 20, cursor = null }) {
  if (!Number.isInteger(limit) || limit < 1) {
    throw new RangeError('Limit must be a whole number of at least 1');
  }
  limit = Math.min(limit, 100);

  const nextCursor = cursor ? parseInt(cursor) : null;
  const startIndex = nextCursor ? nextCursor + 1 : 0;

  const sortedItems = items.sort((a, b) => a.id - b.id);
  const pageItems = sortedItems.slice(startIndex, startIndex + limit);
  const hasMore = sortedItems.length > startIndex + limit;

  return { items: pageItems, nextCursor, hasMore };
}

export class InvalidCursorError extends Error {
  constructor(message) {
    super(message);
    this.name = 'InvalidCursorError';
  }
}

export function parseCursorParams(query) {
  const cursor = query.cursor;
  const limit = parseInt(query.limit);

  if (isNaN(limit) || limit < 1) {
    throw new PageParamsError('Invalid limit value');
  }

  if (cursor) {
    return { cursor, limit };
  } else {
    return { cursor: null, limit };
  }
}

